import socket, json, subprocess, time, base64, os, sys
FF="/Applications/Firefox.app/Contents/MacOS/firefox"
S=os.path.dirname(os.path.abspath(__file__))
class Marionette:
    def __init__(self, width=1920, height=1080, port=2828):
        self.proc=subprocess.Popen([FF,"-headless","-marionette","-no-remote","-new-instance","-profile",S+"/ffprof","-width",str(width),"-height",str(height),"about:blank"],stdout=open(S+"/ff.out","w"),stderr=subprocess.STDOUT)
        self.sock=None
        for i in range(120):
            try:
                self.sock=socket.create_connection(("127.0.0.1",port),timeout=2); break
            except Exception: time.sleep(0.5)
        if not self.sock: raise RuntimeError("no marionette")
        self.sock.settimeout(120)
        self.buf=b""; self.id=0
        hello=self._recv()
        self.send("WebDriver:NewSession",{"capabilities":{"alwaysMatch":{"acceptInsecureCerts":True}}})
    def _recv(self):
        while b":" not in self.buf:
            d=self.sock.recv(65536)
            if not d: raise RuntimeError("closed")
            self.buf+=d
        n,rest=self.buf.split(b":",1)
        n=int(n)
        while len(rest)<n:
            d=self.sock.recv(65536)
            if not d: raise RuntimeError("closed")
            rest+=d
        msg=rest[:n]; self.buf=rest[n:]
        return json.loads(msg.decode("utf-8"))
    def send(self,name,params):
        self.id+=1
        body=json.dumps([0,self.id,name,params]).encode("utf-8")
        self.sock.sendall(str(len(body)).encode()+b":"+body)
        while True:
            r=self._recv()
            if isinstance(r,list) and r[0]==1 and r[1]==self.id:
                if r[2]: raise RuntimeError(json.dumps(r[2])[:2000])
                return r[3]
    def navigate(self,url): return self.send("WebDriver:Navigate",{"url":url})
    def exec(self,script,args=None,timeout=60000):
        return self.send("WebDriver:ExecuteScript",{"script":script,"args":args or [],"scriptTimeout":timeout}).get("value")
    def exec_async(self,script,args=None,timeout=60000):
        return self.send("WebDriver:ExecuteAsyncScript",{"script":script,"args":args or [],"scriptTimeout":timeout}).get("value")
    def screenshot(self,path):
        r=self.send("WebDriver:TakeScreenshot",{"full":False,"hash":False})
        open(path,"wb").write(base64.b64decode(r["value"]))
    def set_size(self,w,h): return self.send("WebDriver:SetWindowRect",{"width":w,"height":h})
    def quit(self):
        try: self.send("Marionette:Quit",{"flags":["eForceQuit"]})
        except Exception: pass
        try: self.proc.wait(timeout=10)
        except Exception: self.proc.kill()
if __name__=="__main__":
    m=Marionette()
    html="<html><body><canvas id=c></canvas><script>var gl=document.getElementById('c').getContext('webgl');window.info=gl?(gl.getParameter(gl.VERSION)+' | '+(function(){var e=gl.getExtension('WEBGL_debug_renderer_info');return e?gl.getParameter(e.UNMASKED_RENDERER_WEBGL):'?'})()+' | maxTex '+gl.getParameter(gl.MAX_TEXTURE_SIZE)+' | float '+!!gl.getExtension('OES_texture_float')):'NO WEBGL';var ac=null;try{ac=new AudioContext();window.info+=' | audio '+ac.state+' sr '+ac.sampleRate;}catch(e){window.info+=' | audio err '+e}</script></body></html>"
    m.navigate("data:text/html;base64,"+base64.b64encode(html.encode()).decode())
    time.sleep(1)
    print(m.exec("return window.info"))
    print(m.exec("return [window.innerWidth, window.innerHeight, window.devicePixelRatio]"))
    m.quit()
EOF
cd $S && timeout 120 python3 ff.py; echo "exit $?"; tail -5 $S/ff.out

