const btnToggle = document.getElementById('btn-toggle');
const btnRefire = document.getElementById('btn-refire');
const iconPlay = document.getElementById('icon-play');
const iconPause = document.getElementById('icon-pause');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

let state = 'COUNTDOWN';          // COUNTDOWN | PLAYING | PAUSED | REFIRE_HOLD | ENDED
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0, holdElapsed = 0;
let lastFrameTime = null;

function showCountdown(text) { countdownEl.style.display = 'block'; countdownEl.textContent = text; }
function hideCountdown() { countdownEl.style.display = 'none'; countdownEl.textContent = ''; }
function setPlayIcon(playing) {
  iconPause.style.display = playing ? '' : 'none';
  iconPlay.style.display = playing ? 'none' : '';
  btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function setState(s) { state = s; AUDIO.setAudible(state === 'PLAYING'); }
function resetToStart() { simTime = 0; scrubber.value = '0'; AUDIO.onSeek(0); renderAt(0); }

btnToggle.addEventListener('click', () => {
  if (state === 'PLAYING') { setState('PAUSED'); setPlayIcon(false); }
  else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') { hideCountdown(); resetToStart(); setState('PAUSED'); setPlayIcon(false); }
  else if (state === 'PAUSED') { AUDIO.onSeek(simTime); setState('PLAYING'); setPlayIcon(true); }
  else if (state === 'ENDED') { hideCountdown(); resetToStart(); setState('PLAYING'); setPlayIcon(true); }
});
btnRefire.addEventListener('click', () => {
  hideCountdown();
  countdownElapsed = 0; holdElapsed = 0;
  resetToStart();
  setPlayIcon(true);
  setState('REFIRE_HOLD');
});
pills.forEach(p => p.addEventListener('click', () => {
  playbackSpeed = parseFloat(p.getAttribute('data-speed'));
  pills.forEach(q => { const on = q === p; q.classList.toggle('is-active', on); q.setAttribute('aria-checked', on ? 'true' : 'false'); });
}));
scrubber.addEventListener('input', () => {
  hideCountdown();
  simTime = clamp(parseFloat(scrubber.value) || 0, 0, DURATION);
  setState('PAUSED'); setPlayIcon(false);
  AUDIO.onSeek(simTime);
  renderAt(simTime);
});
window.addEventListener('pointerdown', () => AUDIO.resume());
window.addEventListener('keydown', () => AUDIO.resume());

// initial resting scene, then the countdown starts on the first animation frame
showCountdown('3');
renderAt(0);
function frame(now) {
  requestAnimationFrame(frame);
  const nowS = now / 1000;
  const dt = lastFrameTime === null ? 0 : Math.min(nowS - lastFrameTime, 0.1);
  lastFrameTime = nowS;
  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3) { hideCountdown(); setState('PLAYING'); setPlayIcon(true); }
    else showCountdown(countdownElapsed < 1 ? '3' : (countdownElapsed < 2 ? '2' : '1'));
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1) setState('PLAYING');
  } else if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    scrubber.value = simTime.toFixed(3);
    if (simTime >= DURATION) {
