      renderAt(simTime);
      setState('ENDED'); setPlayIcon(false);
      AUDIO.update(simTime, dt, state);
      return;
    }
  }
  renderAt(simTime);
  AUDIO.update(simTime, dt, state);
}
requestAnimationFrame(frame);
</script>
